#!/usr/bin/env python3
"""
generate_preflight.py — claude-coding-contract-compiler v2.7.0
Emit a runnable preflight.sh from a contract instance.

The generator executes resume_from.verify_before_starting exactly as emitted by the
compiler. It never strips inline comments or substitutes ecosystem-specific commands.
Multiline commands fail closed because preflight commands are intentionally one shell line.
"""
import argparse, json, shlex, sys
from pathlib import Path

PREFLIGHT_TEMPLATE = """#!/usr/bin/env bash
# preflight.sh — {contract_id}
# Auto-generated by claude-coding-contract-compiler v2.7.0
# Run before starting this Claude Code session. Exits 1 if any precondition is unmet.
set -euo pipefail

echo "[preflight] {contract_id}"
echo "[preflight] Checking prerequisites..."

FAILED=0

{checks}

if [ "$FAILED" -ne 0 ]; then
  echo "[preflight] FAILED: $FAILED precondition(s) unmet."
  echo "[preflight] {if_assumption_false}"
  exit 1
fi

echo "[preflight] All preconditions met. Safe to begin."
"""

CHECK_CMD_TEMPLATE = """printf '[preflight] Verifying: %s\\n' {display}
if ! {cmd} > /dev/null 2>&1; then
  printf '[preflight] FAIL: %s\\n' {display}
  FAILED=$((FAILED+1))
fi
"""


def generate(contract: dict, output_dir: Path) -> None:
    cid = contract["contract_id"]
    resume = contract.get("resume_from", {})
    cmds = resume.get("verify_before_starting", [])
    halt_msg = resume.get("if_assumption_false", "HALT RESUME_PRECONDITION_NOT_SATISFIED")

    checks = []
    for index, raw in enumerate(cmds):
        if not isinstance(raw, str) or not raw.strip():
            raise ValueError(f"{cid}: preflight command {index} must be a non-empty string")
        if "\n" in raw or "\r" in raw:
            raise ValueError(f"{cid}: preflight command {index} must be a single-line shell command")
        executable = raw.strip()
        checks.append(CHECK_CMD_TEMPLATE.format(cmd=executable, display=shlex.quote(executable)).rstrip())

    script = PREFLIGHT_TEMPLATE.format(
        contract_id=cid,
        checks="\n\n".join(checks),
        if_assumption_false=halt_msg,
    )

    out_path = output_dir / cid / "preflight.sh"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(script)
    out_path.chmod(0o755)
    print(f"  {cid}: {out_path}")


def main():
    ap = argparse.ArgumentParser(description="Emit preflight.sh per contract instance.")
    ap.add_argument("instances", nargs="+")
    ap.add_argument("--output-dir", default=".")
    args = ap.parse_args()
    out = Path(args.output_dir)
    for path in args.instances:
        c = json.loads(Path(path).read_text())
        generate(c, out)
    print("Done.")


if __name__ == "__main__":
    main()
